class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        INF = float('inf')
        # dp[i]: min partitions of s[:i]
        dp = [INF] * (n + 1)
        dp[0] = 0
        # bal[j][i] True if s[j:i] is balanced
        bal = [[False] * (n + 1) for _ in range(n + 1)]
        for j in range(n):
            counts = [0] * 26
            distinct = 0
            maxc = 0
            for i in range(j + 1, n + 1):
                c = ord(s[i - 1]) - ord('a')
                if counts[c] == 0:
                    distinct += 1
                counts[c] += 1
                if counts[c] > maxc:
                    maxc = counts[c]
                length = i - j
                if distinct * maxc == length:
                    bal[j][i] = True
        for i in range(1, n + 1):
            for j in range(i):
                if bal[j][i] and dp[j] + 1 < dp[i]:
                    dp[i] = dp[j] + 1
        return dp[n]
