    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            count = [0] * 26
            cnt_of_count = [0] * (n + 2)
            distinct = 0
            maxc = 0
            # iterate j from i-1 down to 0, substring s[j:i]
