                    cnt_of_count[old] -= 1
                count[c] = old + 1
                cnt_of_count[old + 1] += 1
                if old + 1 > maxc:
                    maxc = old + 1
                if cnt_of_count[maxc] == distinct:
                    if dp[j] + 1 < dp[i]:
                        dp[i] = dp[j] + 1
        return dp[n]

